css:
@font-face{font-family:'Serif';src:url(node_modules/@fontsource/dm-serif-display/files/dm-serif-display-latin-400-normal.woff2)}
@font-face{font-family:'Serif';font-style:italic;src:url(node_modules/@fontsource/dm-serif-display/files/dm-serif-display-latin-400-italic.woff2)}
@font-face{font-family:'Work';src:url(node_modules/@fontsource/work-sans/files/work-sans-latin-500-normal.woff2);font-weight:500}
@font-face{font-family:'Work';src:url(node_modules/@fontsource/work-sans/files/work-sans-latin-700-normal.woff2);font-weight:700}
@font-face{font-family:'Plex';src:url(node_modules/@fontsource/ibm-plex-mono/files/ibm-plex-mono-latin-600-normal.woff2);font-weight:600}
.card{background:#EFE6D2;color:#1F3A2E;font-family:'Work';font-weight:500}
.card::before{content:'';position:absolute;left:40px;right:40px;top:40px;bottom:40px;border:5px solid #1F3A2E;outline:2px solid #1F3A2E;outline-offset:-18px}
.scales{position:absolute;left:40px;right:40px;height:70px;background-color:#1F3A2E;background-image:radial-gradient(circle at 50% 0,#EFE6D2 0 16px,transparent 17px),radial-gradient(circle at 50% 0,#B6532C 0 22px,transparent 23px);background-size:56px 36px;background-position:0 0,28px 18px}
.scales.top{top:150px} .scales.bot{bottom:150px}
.safe{z-index:2;padding-left:40px}
.plate{font:600 36px 'Plex';letter-spacing:3px;text-transform:uppercase;color:#B6532C;margin:0 0 26px}
h1{font-family:'Serif';font-weight:400;font-size:128px;line-height:1.0;margin:0;letter-spacing:-1px;max-width:850px}
h1 em{color:#B6532C;font-style:italic}
.lbl{font:500 52px/1.3 'Work';margin:30px 0 0;max-width:820px}
.lbl b{font-weight:700;color:#B6532C}
.big{font-family:'Serif';font-size:280px;line-height:.85;margin:0;color:#B6532C}
.spec{border:4px solid #1F3A2E;background:#F8F2E4;padding:30px 34px;margin-top:34px;max-width:800px;box-shadow:10px 10px 0 #1F3A2E}
.spec .k{font:600 34px 'Plex';color:#B6532C;letter-spacing:2px;text-transform:uppercase;display:block;margin-bottom:8px}
.spec .v{font:500 50px/1.25 'Work'}
.row{display:flex;gap:30px;align-items:center;border-top:4px solid #1F3A2E;padding:26px 0;max-width:820px}
.row:last-child{border-bottom:4px solid #1F3A2E}
.row b{font-family:'Serif';font-weight:400;font-size:100px;color:#B6532C;min-width:100px}
.row span{font:500 52px/1.2 'Work'}
.card-1{background:#1F3A2E;color:#EFE6D2}
.card-1::before{border-color:#EFE6D2;outline-color:#EFE6D2}
.card-1 .scales{background-color:#B6532C;background-image:radial-gradient(circle at 50% 0,#1F3A2E 0 16px,transparent 17px),radial-gradient(circle at 50% 0,#EFE6D2 0 22px,transparent 23px)}
.card-1 h1{font-size:150px;line-height:.98} .card-1 h1 em{color:#F0A27E}
.card-1 .plate{color:#F0A27E}
.end h1{font-size:118px} .end .handle{font:700 60px 'Work';margin-top:50px;color:#B6532C}
 .spec{padding:34px 40px} .spec .k{font-size:40px} .spec .v{font-size:60px}
